<script src="/assets/wikrama/js/swiper-bundle.min.js"></script>
<script>
document.addEventListener('DOMContentLoaded', function() {
    // Smart Sticky Navbar: Hide on scroll down, Show on scroll up
    var navEl = document.getElementById('wrapper-navbar');
    var lastScrollY = window.pageYOffset || document.documentElement.scrollTop;
    var scrollThreshold = 10;

    function handleNavbarScroll() {
        if (!navEl) return;
        var currentScrollY = window.pageYOffset || document.documentElement.scrollTop;

        if (currentScrollY <= 80) {
            // At top: transparent, original state
            navEl.classList.add('nav-at-top');
            navEl.classList.remove('nav-hidden', 'nav-visible', 'uicore-scrolled');
            lastScrollY = currentScrollY;
            return;
        }

        var diff = currentScrollY - lastScrollY;
        if (Math.abs(diff) < scrollThreshold) {
            return;
        }

        if (diff > 0) {
            // Scrolling DOWN -> HILANG (Hide completely)
            navEl.classList.remove('nav-at-top', 'nav-visible');
            navEl.classList.add('nav-hidden');
        } else {
            // Scrolling UP -> BARU MUNCUL (Show with solid white & visible dark text)
            navEl.classList.remove('nav-at-top', 'nav-hidden');
            navEl.classList.add('nav-visible', 'uicore-scrolled');
        }

        lastScrollY = currentScrollY <= 0 ? 0 : currentScrollY;
    }
    window.addEventListener('scroll', handleNavbarScroll, { passive: true });
    handleNavbarScroll();

    function initAllSwipers() {
        if (typeof Swiper === 'undefined') return;

        // Hero Slider
        var heroEl = document.querySelector('.elementor-widget-uicore-custom-slider .swiper');
        if (heroEl && !heroEl.swiper) {
            try {
                new Swiper(heroEl, {
                    loop: true,
                    effect: 'fade',
                    fadeEffect: { crossFade: true },
                    autoplay: { delay: 5000, disableOnInteraction: false },
                    navigation: {
                        nextEl: '.elementor-widget-uicore-custom-slider .ui-e-next',
                        prevEl: '.elementor-widget-uicore-custom-slider .ui-e-previous',
                    },
                    speed: 800
                });
            } catch(e) { console.error('Hero swiper init error:', e); }
        }

        // News Loop Carousel
        var newsEl = document.querySelector('.elementor-widget-loop-carousel .swiper');
        if (newsEl && !newsEl.swiper) {
            try {
                new Swiper(newsEl, {
                    loop: true,
                    slidesPerView: 3,
                    spaceBetween: 30,
                    autoplay: { delay: 4000, disableOnInteraction: false },
                    breakpoints: {
                        320: { slidesPerView: 1, spaceBetween: 15 },
                        768: { slidesPerView: 2, spaceBetween: 20 },
                        1024: { slidesPerView: 3, spaceBetween: 30 },
                        1440: { slidesPerView: 4, spaceBetween: 30 }
                    }
                });
            } catch(e) { console.error('News swiper init error:', e); }
        }
        // Progress Bars Animate on Scroll
        var progressContainer = document.querySelector('.elementor-element-da04a90');
        var progressBars = document.querySelectorAll('.elementor-widget-progress .elementor-progress-bar');
        if (progressBars.length > 0 && progressContainer && 'IntersectionObserver' in window) {
            var pObserver = new IntersectionObserver(function(entries) {
                if (entries[0].isIntersecting) {
                    progressBars.forEach(function(bar) {
                        var max = bar.getAttribute('data-max') || '100';
                        bar.style.width = max + '%';
                    });
                    pObserver.disconnect();
                }
            }, { threshold: 0.15 });
            pObserver.observe(progressContainer);
        }
    }

    initAllSwipers();
    setTimeout(initAllSwipers, 800);
});
</script>
